inline nlohmann::json TurnSample::ToJson() const
{
	auto json = nlohmann::json::object();

	json["serverId"] = serverId;
	if (allocations.has_value())
	{
		json["allocations"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*allocations)) items.push_back(item.ToJson()); return items; }();
	}
	if (sessions.has_value())
	{
		json["sessions"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*sessions)) items.push_back(item.ToJson()); return items; }();
	}

	return json;
}

inline TurnSample TurnSample::FromJson(const nlohmann::json& json)
{
	TurnSample result;

	if (!json.is_object())
	{
		return result;
	}

	if (auto value = detail::Read<std::string>(json, "serverId"))
	{
		result.serverId = std::move(*value);
	}
	if (auto it = json.find("allocations"); it != json.end() && it->is_array())
	{
		std::vector<TurnPeerAllocation> items;

		for (const auto& item : *it)
		{
			items.push_back(TurnPeerAllocation::FromJson(item));
		}

		result.allocations = std::move(items);
	}
	if (auto it = json.find("sessions"); it != json.end() && it->is_array())
	{
		std::vector<TurnSession> items;

		for (const auto& item : *it)
		{
			items.push_back(TurnSession::FromJson(item));
		}

		result.sessions = std::move(items);
	}

	return result;
}

