inline nlohmann::json CustomSfuEvent::ToJson() const
{
	auto json = nlohmann::json::object();

	json["name"] = name;
	if (value.has_value())
	{
		json["value"] = (*value);
	}
	if (transportId.has_value())
	{
		json["transportId"] = (*transportId);
	}
	if (sfuStreamId.has_value())
	{
		json["sfuStreamId"] = (*sfuStreamId);
	}
	if (sfuSinkId.has_value())
	{
		json["sfuSinkId"] = (*sfuSinkId);
	}
	if (message.has_value())
	{
		json["message"] = (*message);
	}
	if (!attachments.is_null())
	{
		json["attachments"] = attachments;
	}
	if (timestamp.has_value())
	{
		json["timestamp"] = detail::WholeOrFraction((*timestamp));
	}

	return json;
}

inline CustomSfuEvent CustomSfuEvent::FromJson(const nlohmann::json& json)
{
	CustomSfuEvent result;

	if (!json.is_object())
	{
		return result;
	}

	if (auto value = detail::Read<std::string>(json, "name"))
	{
		result.name = std::move(*value);
	}
	result.value = detail::Read<std::string>(json, "value");
	result.transportId = detail::Read<std::string>(json, "transportId");
	result.sfuStreamId = detail::Read<std::string>(json, "sfuStreamId");
	result.sfuSinkId = detail::Read<std::string>(json, "sfuSinkId");
	result.message = detail::Read<std::string>(json, "message");
	if (auto it = json.find("attachments"); it != json.end() && !it->is_null())
	{
		result.attachments = *it;
	}
	result.timestamp = detail::Read<double>(json, "timestamp");

	return result;
}

inline nlohmann::json SfuSample::ToJson() const
{
	auto json = nlohmann::json::object();

	json["sfuId"] = sfuId;
	json["timestamp"] = detail::WholeOrFraction(timestamp);
	if (timeZoneOffsetInHours.has_value())
	{
		json["timeZoneOffsetInHours"] = (*timeZoneOffsetInHours);
	}
	if (marker.has_value())
	{
		json["marker"] = (*marker);
	}
	if (customSfuEvents.has_value())
	{
		json["customSfuEvents"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*customSfuEvents)) items.push_back(item.ToJson()); return items; }();
	}
	if (transports.has_value())
	{
		json["transports"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*transports)) items.push_back(item.ToJson()); return items; }();
	}
	if (inboundRtpPads.has_value())
	{
		json["inboundRtpPads"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*inboundRtpPads)) items.push_back(item.ToJson()); return items; }();
	}
	if (outboundRtpPads.has_value())
	{
		json["outboundRtpPads"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*outboundRtpPads)) items.push_back(item.ToJson()); return items; }();
	}
	if (sctpChannels.has_value())
	{
		json["sctpChannels"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*sctpChannels)) items.push_back(item.ToJson()); return items; }();
	}
	if (extensionStats.has_value())
	{
		json["extensionStats"] = [&]() { auto items = nlohmann::json::array(); for (const auto& item : (*extensionStats)) items.push_back(item.ToJson()); return items; }();
	}

	return json;
}

inline SfuSample SfuSample::FromJson(const nlohmann::json& json)
{
	SfuSample result;

	if (!json.is_object())
	{
		return result;
	}

	if (auto value = detail::Read<std::string>(json, "sfuId"))
	{
		result.sfuId = std::move(*value);
	}
	if (auto value = detail::Read<double>(json, "timestamp"))
	{
		result.timestamp = std::move(*value);
	}
	result.timeZoneOffsetInHours = detail::Read<int64_t>(json, "timeZoneOffsetInHours");
	result.marker = detail::Read<std::string>(json, "marker");
	if (auto it = json.find("customSfuEvents"); it != json.end() && it->is_array())
	{
		std::vector<CustomSfuEvent> items;

		for (const auto& item : *it)
		{
			items.push_back(CustomSfuEvent::FromJson(item));
		}

		result.customSfuEvents = std::move(items);
	}
	if (auto it = json.find("transports"); it != json.end() && it->is_array())
	{
		std::vector<SfuTransport> items;

		for (const auto& item : *it)
		{
			items.push_back(SfuTransport::FromJson(item));
		}

		result.transports = std::move(items);
	}
	if (auto it = json.find("inboundRtpPads"); it != json.end() && it->is_array())
	{
		std::vector<SfuInboundRtpPad> items;

		for (const auto& item : *it)
		{
			items.push_back(SfuInboundRtpPad::FromJson(item));
		}

		result.inboundRtpPads = std::move(items);
	}
	if (auto it = json.find("outboundRtpPads"); it != json.end() && it->is_array())
	{
		std::vector<SfuOutboundRtpPad> items;

		for (const auto& item : *it)
		{
			items.push_back(SfuOutboundRtpPad::FromJson(item));
		}

		result.outboundRtpPads = std::move(items);
	}
	if (auto it = json.find("sctpChannels"); it != json.end() && it->is_array())
	{
		std::vector<SfuSctpChannel> items;

		for (const auto& item : *it)
		{
			items.push_back(SfuSctpChannel::FromJson(item));
		}

		result.sctpChannels = std::move(items);
	}
	if (auto it = json.find("extensionStats"); it != json.end() && it->is_array())
	{
		std::vector<SfuExtensionStats> items;

		for (const auto& item : *it)
		{
			items.push_back(SfuExtensionStats::FromJson(item));
		}

		result.extensionStats = std::move(items);
	}

	return result;
}

